script:
frappe.ui.form.on('Purchase Receipt Item', {
    qty: function(frm, cdt, cdn) {
        calculate_conversion(frm, cdt, cdn);
    },
    custom_total_stock_qty: function(frm, cdt, cdn) {
        calculate_conversion(frm, cdt, cdn);
    },
    uom: function(frm, cdt, cdn) {
        calculate_conversion(frm, cdt, cdn);
    },
    on_submit: async function(frm) {

        for (let row of frm.doc.items) {

            if (!row.serial_and_batch_bundle || !row.conversion_factor) continue;

            let bundle = await frappe.db.get_doc(
                'Serial and Batch Bundle',
                row.serial_and_batch_bundle
            );

            for (let entry of (bundle.entries || [])) {

                if (entry.batch_no) {
                    await frappe.db.set_value(
                        'Batch',
                        entry.batch_no,
                        'custom_conversion_factor',
                        row.conversion_factor
                    );
                }
            }
        }
    }
});

function calculate_conversion(frm, cdt, cdn) {
    let row = locals[cdt][cdn];

    // Only apply when UOM != Stock UOM
    if (row.uom && row.stock_uom && row.uom !== row.stock_uom) {

        if (row.qty && row.custom_total_stock_qty) {
            let conversion = flt(row.custom_total_stock_qty / row.qty);

            frappe.model.set_value(cdt, cdn, 'conversion_factor', conversion);
            frappe.model.set_value(cdt, cdn, 'stock_qty', row.custom_total_stock_qty);
        }
    }
}

frappe.ui.form.on('Stock Entry Detail', {
    batch_no: apply_conversion,
    qty: apply_conversion,
    item_code: apply_conversion
});

async function apply_conversion(frm, cdt, cdn) {
    let row = locals[cdt][cdn];

    if (!row.batch_no || !row.qty) return;

    try {
        let r = await frappe.db.get_value(
            'Batch',
            row.batch_no,
            'custom_conversion_factor'
        );

        let conv = r.message.custom_conversion_factor || 1;

        // Set conversion factor
        await frappe.model.set_value(cdt, cdn, 'conversion_factor', conv);

        // Let ERPNext calculate stock_qty automatically
        // OR force if needed:
        await frappe.model.set_value(cdt, cdn, 'stock_qty', row.qty * conv);

    } catch (e) {
        console.error(e);
    }
}

