frappe.ui.form.on('Employee', {
    validate(frm) {
        if (frm.doc.custom_aadhar_card_number) {

            const aadhar =

                frm.doc.custom_aadhar_card_number

                    .replace(/\s+/g, '');

            if (!/^\d{12}$/.test(aadhar)) {

                frappe.throw(

                    'Aadhar Card Number must contain exactly 12 digits'

                );

            }

            // Direct assignment

            frm.doc.custom_aadhar_card_number = aadhar;

        }

        // PAN Validation

        if (frm.doc.pan_number) {

            const pan =

                frm.doc.pan_number

                    .toUpperCase();

            if (!/^[A-Z]{5}[0-9]{4}[A-Z]{1}$/.test(pan)) {

                frappe.throw(

                    'Invalid PAN Card Number Format'

                );

            }

            // Direct assignment

            frm.doc.custom_pan_number = pan;

        }

    },
    refresh(frm) {

        render_document_preview_buttons(frm);

        const is_employee_self_service =
            frappe.user.has_role("Employee Self Service");

        const is_hr_or_admin =
            frappe.user.has_role("HR Manager") ||
            frappe.user.has_role("HR User") ||
            frappe.user.has_role("System Manager");

        if (!is_employee_self_service || is_hr_or_admin) {
            return;
        }

        const editable_sections = [
            "personal_details_section",
            "emergency_contact_section",
            "custom_aadhar",
            "bank_details_section",
            "custom_section_break_y1u7h",
            "address_section",
            "emergency_contact_details",
            "custom_nominee_details"
        ];

        const skip_fieldtypes = [
            "Section Break",
            "Column Break",
            "Tab Break",
            "HTML",
            "Button"
        ];

        // Make readonly
        frm.fields.forEach(field => {

            if (
                !field.df.fieldname ||
                skip_fieldtypes.includes(field.df.fieldtype)
            ) {
                return;
            }

            frm.set_df_property(
                field.df.fieldname,
                "read_only",
                1
            );
        });

        // Allow editable sections
        let allow = false;

        frm.fields.forEach(field => {

            if (field.df.fieldtype === "Section Break") {

                allow = editable_sections.includes(
                    field.df.fieldname
                );

                return;
            }

            if (
                !field.df.fieldname ||
                skip_fieldtypes.includes(field.df.fieldtype)
            ) {
                return;
            }

            if (allow) {

                frm.set_df_property(
                    field.df.fieldname,
                    "read_only",
                    0
                );
            }
        });
    },

    custom_aadhar_card(frm) {
        render_document_preview_buttons(frm);
    },

    custom_pan_card(frm) {
        render_document_preview_buttons(frm);
    }
});


function render_document_preview_buttons(frm) {

    const fields = [
        {
            label: "Aadhar Card",
            fieldname: "custom_aadhar_card"
        },
        {
            label: "PAN Card",
            fieldname: "custom_pan_card"
        }
    ];

    let html = `
        <div style="
            display:flex;
            gap:10px;
            flex-wrap:wrap;
        ">
    `;

    fields.forEach(doc => {

        const file_url = frm.doc[doc.fieldname];

        if (!file_url) {
            return;
        }

        html += `
            <button
                class="btn btn-default btn-sm preview-document-btn"
                data-file="${file_url}"
                data-label="${doc.label}"
                style="margin-bottom:10px"
            >
                Preview ${doc.label}
            </button>
        `;
    });

    html += `</div>`;

    frm.fields_dict.custom_document_preview.$wrapper.html(html);

    // Button click
    frm.fields_dict.custom_document_preview.$wrapper
        .find('.preview-document-btn')
        .on('click', function () {

            const file_url = $(this).data('file');
            const label = $(this).data('label');

            open_document_preview_dialog(file_url, label);
        });
}


function open_document_preview_dialog(file_url, label) {

    const extension = file_url
        .split('.')
        .pop()
        .toLowerCase();

    let content = '';

    // Image Preview
    if ([
        'jpg',
        'jpeg',
        'png',
        'webp'
    ].includes(extension)) {

        content = `
            <div style="text-align:center">
                <img
                    src="${file_url}"
                    style="
                        max-width:100%;
                        max-height:75vh;
                        border-radius:10px;
                    "
                />
            </div>
        `;
    }

    // PDF Preview
    else if (extension === 'pdf') {

        content = `
            <iframe
                src="${file_url}"
                width="100%"
                height="700px"
                style="border:none"
            ></iframe>
        `;
    }

    // Other Files
    else {

        content = `
            <div style="padding:20px;text-align:center">
                <a
                    href="${file_url}"
                    target="_blank"
                    class="btn btn-primary"
                >
                    Open File
                </a>
            </div>
        `;
    }

    const dialog = new frappe.ui.Dialog({
        title: label,
        size: 'extra-large',
        fields: [
            {
                fieldtype: 'HTML',
                fieldname: 'preview_html'
            }
        ]
    });

    dialog.fields_dict.preview_html.$wrapper.html(content);

    dialog.show();
}

frappe.listview_settings["Shift Type"] = {

    onload(listview) {

        listview.page.add_inner_button(
            "Regularize Shift Attendance",
            () => {

                const d = new frappe.ui.Dialog({

                    title: "Regularize Shift Attendance",

                    fields: [

                        {
                            label: "Shift Type",
                            fieldname: "shift_type",
                            fieldtype: "Link",
                            options: "Shift Type"
                        },

                        {
                            label: "Employee",
                            fieldname: "employee",
                            fieldtype: "Link",
                            options: "Employee"
                        },

                        {
                            label: "From Date",
                            fieldname: "from_date",
                            fieldtype: "Date",
                            reqd: 1,
                            default: frappe.datetime.month_start()
                        },

                        {
                            label: "To Date",
                            fieldname: "to_date",
                            fieldtype: "Date",
                            reqd: 1,
                            default: frappe.datetime.month_end()
                        }

                    ],

                    primary_action_label: "Run",

                    async primary_action(values) {

                        if (
                            values.from_date > values.to_date
                        ) {
                            frappe.msgprint(
                                __("From Date cannot be greater than To Date")
                            );

                            return;
                        }

                        frappe.call({

                            method:
                                "regularize_consecutive_shift",

                            args: values,

                            freeze: true,

                            freeze_message:
                                __("Regularizing shifts..."),

                            callback(r) {

                                let message =
                                    r.message?.message || r.message;

                                if (Array.isArray(message)) {
                                    message = message.join("<br>");
                                }

                                frappe.msgprint({
                                    title: __("Result"),
                                    message: message || __("Completed")
                                });

                                d.hide();

                                listview.refresh();

                            }

                        });

                    }

                });

                d.show();

            }
        );

    }

};
